parameters.jsCode:
// Parse incoming chat message
const data = $input.first().json.body;

return {
  json: {
    sessionId: data.sessionId || `session-${Date.now()}`,
    messageId: data.messageId || `msg-${Date.now()}`,
    userMessage: data.message || data.text || '',
    userId: data.userId || data.visitorId,
    userName: data.name || 'Visitor',
    userEmail: data.email || null,
    userPhone: data.phone || null,
    timestamp: new Date().toISOString(),
    conversationHistory: data.history || [],
    metadata: {
      source: data.source || 'website',
      page: data.page || 'unknown',
      referrer: data.referrer || null,
      utm_source: data.utm_source || null,
      utm_campaign: data.utm_campaign || null
    }
  }
};

// Intelligent intent detection for insurance queries
const message = $input.first().json.userMessage.toLowerCase();

let intent = 'general';
let confidence = 0;
let suggestedResponse = '';

// Life Insurance Intent
if (message.match(/life insurance|term life|whole life|universal life|death benefit/i)) {
  intent = 'life_insurance_inquiry';
  confidence = 0.9;
  suggestedResponse = 'life_insurance';
}
// Health Insurance Intent
else if (message.match(/health insurance|medical insurance|aca|obamacare|health plan|medicaid|medicare/i)) {
  intent = 'health_insurance_inquiry';
  confidence = 0.9;
  suggestedResponse = 'health_insurance';
}
// Pricing Intent
else if (message.match(/how much|cost|price|rate|premium|quote|save money|cheaper/i)) {
  intent = 'pricing_inquiry';
  confidence = 0.85;
  suggestedResponse = 'pricing_info';
}
// Quote Request
else if (message.match(/get a quote|need quote|want quote|quote me|give me a quote/i)) {
  intent = 'quote_request';
  confidence = 0.95;
  suggestedResponse = 'capture_lead_info';
}
// Coverage Questions
else if (message.match(/what does.*cover|coverage|benefits|what's included|does it cover/i)) {
  intent = 'coverage_question';
  confidence = 0.85;
  suggestedResponse = 'coverage_info';
}
// How It Works
else if (message.match(/how does.*work|how do i|process|steps|application/i)) {
  intent = 'process_question';
  confidence = 0.8;
  suggestedResponse = 'process_explanation';
}
// Talk to Agent
else if (message.match(/speak.*agent|talk.*person|human|representative|call me/i)) {
  intent = 'agent_request';
  confidence = 0.95;
  suggestedResponse = 'route_to_agent';
}
// Greeting
else if (message.match(/^(hi|hello|hey|good morning|good afternoon)/i)) {
  intent = 'greeting';
  confidence = 0.9;
  suggestedResponse = 'welcome_message';
}

return {
  json: {
    ...$input.first().json,
    intent: intent,
    confidence: confidence,
    suggestedResponse: suggestedResponse,
    needsHumanAgent: intent === 'agent_request' || confidence < 0.7
  }
};

